  // Check all elements in the entire document including shadow roots
  function findAll(root, tag) {
    let results = Array.from(root.querySelectorAll(tag));
    const all = root.querySelectorAll('*');
    for (const el of all) {
      if (el.shadowRoot) {
        results = results.concat(findAll(el.shadowRoot, tag));
      }
    }
    return results;
  }

  const videos = findAll(document, 'video').map(v => v.src);
  return {
    videos,
    customTags: Array.from(new Set(Array.from(document.querySelectorAll('*')).map(e => e.tagName).filter(t => t.includes('-'))))
